"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useId, useState } from "react";

import { Switch } from "@/components/motion/switch";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { CircleCheckIcon } from "../parts/icons";
import { BlockFrame } from "../parts/block-frame";
import { CheckRow } from "./release-readiness/check-row";
import { RELEASE_CHECKS, ROLLOUT_WAVES } from "./release-readiness/data";
import { AvatarStack } from "./shared/avatar";
import { LockIcon, RocketIcon } from "./shared/icons";
import { TEAM } from "./shared/people";
import { ProgressBar } from "./shared/progress-bar";

type Phase = "waiting" | "rolling" | "done";

const WAVE_MS = 1100;

/**
 * A release checklist that keeps the checks, the progress and the final action
 * together. The start button stays locked until every check is ticked, and it
 * says why. Starting runs a short simulated rollout, wave by wave.
 */
export function ReleaseReadiness({ className }: { className?: string }) {
  const [checks, setChecks] = useState(RELEASE_CHECKS);
  const [notify, setNotify] = useState(true);
  const [phase, setPhase] = useState<Phase>("waiting");
  const [wave, setWave] = useState(0);
  const reduceMotion = useReducedMotion();
  const titleId = useId();
  const lockId = useId();
  const notifyId = useId();

  const doneCount = checks.filter((check) => check.done).length;
  const left = checks.length - doneCount;
  const ready = left === 0;

  useEffect(() => {
    if (phase !== "rolling") return;
    const timer = window.setTimeout(() => {
      if (wave + 1 >= ROLLOUT_WAVES.length) setPhase("done");
      else setWave(wave + 1);
    }, WAVE_MS);
    return () => window.clearTimeout(timer);
  }, [phase, wave]);

  const toggle = (id: string) =>
    setChecks((current) => current.map((check) => (check.id === id ? { ...check, done: !check.done } : check)));

  const start = () => {
    setWave(0);
    setPhase("rolling");
  };

  const reset = () => {
    setChecks(RELEASE_CHECKS);
    setPhase("waiting");
    setWave(0);
  };

  const rolloutPercent = phase === "done" ? 100 : phase === "rolling" ? ((wave + 0.5) / ROLLOUT_WAVES.length) * 100 : 0;

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("max-w-xl", className)}>
      <header className="flex flex-wrap items-start justify-between gap-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Fernhill 4.2
          </h2>
          <p className="text-sm text-muted-foreground">Clinic workspace, ships Thursday, Nov 12</p>
        </div>
        <AvatarStack people={TEAM.slice(1, 5)} />
      </header>

      <div className="flex flex-col gap-2 px-5 pt-4">
        <div className="flex items-baseline justify-between gap-3 text-sm">
          <span className="relative inline-flex overflow-hidden font-medium" aria-live="polite">
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.span
                key={left}
                initial={reduceMotion ? false : { y: "60%", opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                exit={reduceMotion ? { opacity: 0, transition: { duration: 0 } } : { y: "-60%", opacity: 0 }}
                transition={{ type: "spring", stiffness: 420, damping: 40 }}
              >
                {ready ? "Every check is done" : `${left} ${left === 1 ? "check" : "checks"} left`}
              </motion.span>
            </AnimatePresence>
          </span>
          <span className="tabular-nums text-muted-foreground">
            {doneCount} of {checks.length}
          </span>
        </div>
        <ProgressBar value={(doneCount / checks.length) * 100} label="Checks done" fill={ready ? "bg-chart-2" : "bg-chart-1"} />
      </div>

      <ul aria-label="Release checks" className="flex flex-col gap-0.5 px-2 py-3">
        {checks.map((check) => (
          <CheckRow key={check.id} check={check} locked={phase !== "waiting"} onToggle={toggle} />
        ))}
      </ul>

      <div className="flex flex-col gap-4 border-t border-border px-5 py-4">
        <label htmlFor={notifyId} className="flex cursor-pointer items-center justify-between gap-4 text-sm">
          <span className="flex flex-col">
            <span className="font-medium">Tell the clinic managers channel</span>
            <span className="text-xs text-muted-foreground">Posts when the rollout starts and when it ends</span>
          </span>
          <Switch id={notifyId} checked={notify} onCheckedChange={setNotify} disabled={phase !== "waiting"} />
        </label>

        {phase === "waiting" ? (
          <div className="flex flex-wrap items-center justify-between gap-3">
            <p id={lockId} className="flex items-center gap-2 text-xs text-muted-foreground">
              {ready ? null : <LockIcon className="size-3.5" />}
              {ready ? "Ready when you are." : "Starts once every check is done."}
            </p>
            <Button onClick={start} disabled={!ready} aria-describedby={lockId}>
              {ready ? <RocketIcon /> : <LockIcon />}
              Start release
            </Button>
          </div>
        ) : (
          <div className="flex flex-col gap-2">
            <div className="flex items-center justify-between gap-3 text-sm" role="status">
              <span className="flex items-center gap-2 font-medium">
                {phase === "done" ? <CircleCheckIcon className="size-4 text-marketing-green-ink" /> : null}
                {phase === "done" ? "Live in every clinic" : `Rolling out to ${ROLLOUT_WAVES[wave]}`}
              </span>
              <span className="tabular-nums text-muted-foreground">
                {phase === "done" ? ROLLOUT_WAVES.length : wave} of {ROLLOUT_WAVES.length} waves
              </span>
            </div>
            <ProgressBar value={rolloutPercent} label="Rollout" fill="bg-chart-2" />
            {phase === "done" ? (
              <div className="flex flex-wrap items-center justify-between gap-3 pt-1">
                <p className="text-xs text-muted-foreground">
                  {notify ? "Clinic managers got the release notes." : "Nobody was notified."}
                </p>
                <Button variant="outline" size="sm" onClick={reset}>
                  Plan the next release
                </Button>
              </div>
            ) : null}
          </div>
        )}
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

