"use client";

import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

/** Props for a thin bar that shows how much of something is done. */
export interface ProgressBarProps {
  /** From 0 to 100. */
  value: number;
  /** Names the bar for screen readers, such as "Sprint progress". */
  label: string;
  /** The fill class, such as `bg-chart-2`. */
  fill?: string;
  /** Delay before the fill moves, in seconds, so a parent bar can follow its child. */
  delay?: number;
  className?: string;
}

/**
 * A rounded progress bar that grows from the left on first show and glides to
 * each new value. It grows with a scale transform only, and it is instant under
 * reduced motion.
 */
export function ProgressBar({ value, label, fill = "bg-chart-2", delay = 0, className }: ProgressBarProps) {
  const reduceMotion = useReducedMotion();
  const clamped = Math.max(0, Math.min(100, value));
  return (
    <span
      role="progressbar"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(clamped)}
      className={cn("relative block h-1.5 w-full overflow-hidden rounded-full", className)}
    >
      {/* The track is its own faded layer, so a see-through card does not stack two tints. */}
      <span aria-hidden="true" className="absolute inset-0 bg-muted-foreground/20" />
      <motion.span
        aria-hidden="true"
        className={cn("absolute inset-0 origin-left rounded-full", fill)}
        initial={reduceMotion ? false : { scaleX: 0 }}
        animate={{ scaleX: clamped / 100 }}
        transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 160, damping: 26, delay }}
      />
    </span>
  );
}
